import {W,H,newGame,fire,bestShot,weapons} from './rules.js?v=contrast-10';
import {render} from './render.js?v=contrast-10';
import {swipeAim,guidanceCharges} from './aim.js?v=contrast-10';
import {initDisplay} from './display.js?v=contrast-10';
import * as online from './online.js';
const $=s=>document.querySelector(s),canvas=$('#field'),ctx=canvas.getContext('2d',{alpha:false});const renderScale=Math.min(2,Math.max(1.5,window.devicePixelRatio||1));canvas.width=Math.round(W*renderScale);canvas.height=Math.round(H*renderScale);ctx.setTransform(renderScale,0,0,renderScale,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';
let game=null,kind=null,room=null,animation=null,poll=null,busy=false,lastVersion=-1,guidanceSpent=[0,0],guideUntil=0,guideTimer=null;
const display=initDisplay({hasGame:()=>!!game});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function status(s){$('#status').textContent=s;}function onlineStatus(s){$('#online-status').textContent=s;}
function controls(){const can=!!game&&game.winner===null&&!busy&&(kind!=='online'||(room?.ready&&room.seat===game.turn))&&(kind!=='solo'||game.turn===0);$('#fire').disabled=!can;$('#angle-value').textContent=$('#angle').value+'°';$('#power-value').textContent=$('#power').value+'%';$('#aim-toggle').textContent=`Sigt ${$('#angle').value}° · ${$('#power').value}%`;const power=Number($('#power').value);$('#power-value').style.color=power<42?'#64d99b':power<73?'#f4d26a':'#f18772';$('#player0').innerHTML=game?`<b>${esc(game.players[0].name)}</b><small>♥ ${game.players[0].hp} · ★ ${game.players[0].score} · ◇ ${game.players[0].cash}</small>`:'';$('#player1').innerHTML=game?`<b>${esc(game.players[1].name)}</b><small>♥ ${game.players[1].hp} · ★ ${game.players[1].score} · ◇ ${game.players[1].cash}</small>`:'';$('#round').textContent=game?`RUNDE ${game.round} / ${game.maxRounds}  ·  VIND ${game.wind>0?'→':game.wind<0?'←':'·'} ${Math.abs(game.wind)}`:'';$('#connection').textContent=kind==='online'?'● ONLINE':'● LOKAL';const seat=game?.turn??0,charges=game?guidanceCharges(game.players[seat].score,guidanceSpent[seat]):0;$('#guide').disabled=!can||charges<1||Date.now()<guideUntil;$('#guide').textContent=matchMedia('(any-pointer:coarse) and (orientation:landscape) and (max-height:600px)').matches?(Date.now()<guideUntil?'Bane aktiv':`Bane · ${charges}`):(Date.now()<guideUntil?'Banevisning aktiv':`Banevisning · ${charges}`);display.sync();}
function draw(){const preview=game&&!animation&&Date.now()<guideUntil&&(kind!=='online'||room?.seat===game.turn)?{angle:Number($('#angle').value),power:Number($('#power').value)}:null;render(ctx,game,{animation,preview,aim:game?{player:game.turn,angle:Number($('#angle').value)}:null,time:performance.now()/1000});}
function animate(result,done){animation={...result,index:0,motionIndex:0,path:result.hit.path,hit:result.hit,radius:weapons[result.weapon].radius};function frame(){animation.index+=Math.max(1,Math.ceil(animation.path.length/43));if(animation.index>=animation.path.length)animation.motionIndex=Math.min(animation.motion.length-1,animation.motionIndex+1);draw();if(animation.index<animation.path.length+Math.max(18,animation.motion.length)){requestAnimationFrame(frame);}else{animation=null;draw();done?.();}}requestAnimationFrame(frame);}
function describe(result){const hit=result.damages[1-result.actor],self=result.damages[result.actor];if(game.winner!==null)return `${game.players[game.winner].name} vinder kampen! Slutscore ${game.players[0].score}–${game.players[1].score}.`;if(result.ended)return `Runde ${game.round-1} slut. ${hit?hit+' skade på modstanderen.':''} Ny slagmark!`;return hit?`${game.players[result.actor].name} ramte for ${hit} skade${self?' og tog '+self+' selv':''}.`:`${game.players[result.actor].name} skød. ${self?'Egen skade: '+self+'.':'Ingen træffer.'}`;}
function after(result){status(describe(result));controls();draw();if(kind==='solo'&&game.turn===1&&game.winner===null){busy=true;controls();setTimeout(()=>{const shot=bestShot(game,1);const r=fire(game,shot);animate(r,()=>{busy=false;after(r);});},650);}}
function reset(mode){clearInterval(poll);poll=null;room=null;kind=mode;game=newGame({mode:$('#mode').value,names:mode==='solo'?[$('#name').value.trim()||'Du','Computer']:[$('#name').value.trim()||'Spiller 1','Spiller 2']});lastVersion=-1;busy=false;guidanceSpent=[0,0];guideUntil=0;clearTimeout(guideTimer);document.body.classList.remove('aim-open');$('#aim-toggle').setAttribute('aria-expanded','false');display.enter();status(mode==='solo'?'Din tur. Vælg vinkel og kraft.':'Spiller 1 begynder.');controls();draw();}
$('#aim-toggle').onclick=()=>{const open=document.body.classList.toggle('aim-open');$('#aim-toggle').setAttribute('aria-expanded',String(open));};$('#solo').onclick=()=>reset('solo');$('#local').onclick=()=>reset('local');for(const id of ['angle','power'])$('#'+id).oninput=()=>{controls();draw();};$('#weapon').onchange=controls;
$('#fire').onclick=async()=>{if($('#fire').disabled)return;const shot={angle:Number($('#angle').value),power:Number($('#power').value),weapon:$('#weapon').value};guideUntil=0;clearTimeout(guideTimer);busy=true;controls();try{if(kind==='online'){const next=await online.rpc('aa_fire',{p_code:room.code,p_version:room.version,p_angle:shot.angle,p_power:shot.power,p_weapon:shot.weapon});await sync(next);}else{const result=fire(game,shot);animate(result,()=>{busy=false;after(result);});}}catch(e){status(e.message);busy=false;controls();}};
function adjust(dx,dy){if($('#fire').disabled)return;const next=swipeAim(Number($('#angle').value),Number($('#power').value),dx,dy);$('#angle').value=next.angle;$('#power').value=next.power;controls();draw();}
$('#guide').onclick=()=>{if($('#guide').disabled||!game)return;const seat=game.turn;guidanceSpent[seat]++;if(kind==='online'&&room){try{localStorage.setItem(`aa-guide:${room.code}:${seat}`,String(guidanceSpent[seat]));}catch{}}guideUntil=Date.now()+6000;clearTimeout(guideTimer);guideTimer=setTimeout(()=>{guideUntil=0;controls();draw();},6000);controls();draw();};
let touchState=null;
canvas.addEventListener('touchstart',e=>{if(!display.isActive())return;if(e.cancelable)e.preventDefault();if(e.touches.length!==1){if(touchState)touchState.valid=false;return;}if(!touchState){const p=e.touches[0];touchState={startX:p.clientX,startY:p.clientY,x:p.clientX,y:p.clientY,start:Date.now(),angle:Number($('#angle').value),power:Number($('#power').value),moved:false,valid:true};}},{passive:false});
canvas.addEventListener('touchmove',e=>{if(!display.isActive())return;if(e.cancelable)e.preventDefault();if(!touchState)return;if(e.touches.length!==1){touchState.valid=false;return;}if(!touchState.valid)return;const p=e.touches[0],dx=p.clientX-touchState.startX,dy=p.clientY-touchState.startY;if(Math.hypot(dx,dy)>8)touchState.moved=true;if(touchState.moved&&!$('#fire').disabled){const next=swipeAim(touchState.angle,touchState.power,dx,dy);$('#angle').value=next.angle;$('#power').value=next.power;controls();draw();}},{passive:false});
canvas.addEventListener('touchend',e=>{if(!display.isActive()||!touchState)return;if(e.cancelable)e.preventDefault();if(e.touches.length===0){if(touchState.valid&&!touchState.moved&&Date.now()-touchState.start<350)$('#fire').click();touchState=null;}},{passive:false});canvas.addEventListener('touchcancel',()=>{touchState=null;});
canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse'&&display.isActive())$('#fire').click();});
document.addEventListener('wheel',e=>{if(!display.isActive())return;if(e.cancelable)e.preventDefault();if(e.target.closest('.game')&&!e.target.closest('input,select,button'))adjust(Math.max(-80,Math.min(80,e.deltaX)),Math.max(-80,Math.min(80,e.deltaY)));},{passive:false});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();$('#fire').click();}else if(e.code==='ArrowLeft'||e.code==='ArrowRight'||e.code==='ArrowUp'||e.code==='ArrowDown'){e.preventDefault();adjust(e.code==='ArrowLeft'?-12:e.code==='ArrowRight'?12:0,e.code==='ArrowUp'?-8:e.code==='ArrowDown'?8:0);}});
async function identify(){const p=await online.profile();if(p?.nickname){$('#name').value=p.nickname;onlineStatus(`Logget ind som ${p.nickname}.`);}else onlineStatus('Skriv et ledigt navn og gem profilen.');return p;}
$('#save-name').onclick=async()=>{try{const name=$('#name').value.trim();if(!/^[\p{L}\p{N} _-]{2,20}$/u.test(name))throw Error('Brug 2–20 bogstaver eller tal.');await online.claim(name);await identify();}catch(e){onlineStatus(e.message);}};
$('#player-code').onclick=async()=>{try{const c=await online.createCode();$('#code-result').textContent=`${c.nickname}: ${c.code} — gem koden privat.`;}catch(e){$('#code-result').textContent=e.message;}};
$('#link').onclick=async()=>{try{const r=await online.useCode($('#name').value.trim(),$('#link-code').value.trim());if(r.error)throw Error(r.error);$('#link-code').value='';await identify();$('#code-result').textContent='Profilen er tilknyttet.';}catch(e){$('#code-result').textContent=e.message;}};
async function sync(next){if(!next)return;room=next;$('#room').textContent=`Kampkode: ${next.code} · ${next.ready?'Kampen er klar':'Venter på modstander…'}`;$('#code').value=next.code;let fresh=false;if(!game||kind!=='online'||game.seed!==next.seed){game=newGame({seed:next.seed,mode:next.mode,names:[next.host_name||'Vært',next.guest_name||'Gæst']});kind='online';lastVersion=0;fresh=true;guidanceSpent=[0,0];guideUntil=0;try{guidanceSpent[next.seat]=Number(localStorage.getItem(`aa-guide:${next.code}:${next.seat}`))||0;}catch{}document.body.classList.remove('aim-open');$('#aim-toggle').setAttribute('aria-expanded','false');display.enter();}game.players[0].name=next.host_name||'Vært';game.players[1].name=next.guest_name||'Gæst';if(next.version<lastVersion){game=newGame({seed:next.seed,mode:next.mode,names:[next.host_name,next.guest_name]});lastVersion=0;}const pending=next.shots.slice(lastVersion);let latest=null;for(const shot of pending){if(game.winner!==null)break;latest=fire(game,shot);status(describe(latest));}lastVersion=next.version;if(pending.length===1&&latest){busy=true;controls();animate(latest,()=>{busy=false;controls();draw();});}else{busy=false;controls();draw();}if(fresh)status(next.ready?(next.seat===0?'Din tur.':'Venter på værtens skud.'):'Del kampkoden med en anden spiller.');else if(pending.length&&game.winner===null)status(game.turn===next.seat?'Din tur!':'Modstanderens tur.');}
function startPolling(){clearInterval(poll);poll=setInterval(async()=>{if(!room||document.hidden)return;try{const next=await online.rpc('aa_state',{p_code:room.code});if(next.version!==room.version||next.ready!==room.ready)await sync(next);else{room=next;controls();}}catch(e){onlineStatus('Forbindelsen blev afbrudt: '+e.message);}},3000);}
$('#host').onclick=async()=>{try{await identify();const next=await online.rpc('aa_host',{p_mode:$('#mode').value});await sync(next);startPolling();onlineStatus('Kamp oprettet. Del koden med modstanderen.');}catch(e){onlineStatus(e.message);}};
$('#join').onclick=async()=>{try{await identify();const next=await online.rpc('aa_join',{p_code:$('#code').value.trim()});await sync(next);startPolling();onlineStatus('Du er med i kampen.');}catch(e){onlineStatus(e.message);}};
draw();controls();window.addEventListener('artillery-assets-loaded',draw);

let lastAmbient=0;function ambientFrame(now){if(now-lastAmbient>50&&!document.hidden){draw();lastAmbient=now;}requestAnimationFrame(ambientFrame);}requestAnimationFrame(ambientFrame);
